cd "C:\Users\mnede\Documents\Claude\social-media\repurpose"
$i = 0
foreach ($job in $jobs) {
  $i++
  $start = Get-Date
  Write-Host "[$($start.ToString('HH:mm:ss'))] [$i/$($jobs.Count)] $($job.id)-$($job.slug)"
  node generate-image.js `
    "--image-id=$($job.id)" `
    "--slug=$($job.slug)" `
    "--prefix=yt-posts" `
    "--chat-url=$YTCHAT" `
    "--reference-image=$($job.ref)" `
    "--prompt=$($job.prompt)"
