  Write-Host "[$($end.ToString('HH:mm:ss'))] [$i/$($jobs.Count)] done in $([math]::Round(($end - $start).TotalSeconds))s"
  Write-Host ""
}
Write-Host "All $($jobs.Count) slides regenerated."
